package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Adam Optimizer Training
// Priority 3: 실제 Adam 옵티마이저로 학습
// ==================================================

// trainWithAdam Adam 옵티마이저를 사용한 학습
func trainWithAdam() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Priority 3: Adam Optimizer Training (20 epochs)       ║")
	fmt.Println("║  Hybrid Approach: optimizer.fl reference + Go impl     ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 데이터 로드
	fmt.Println("[1/5] Loading tokenized data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}

	fmt.Printf("✅ Loaded %d tokens from %d vocab\n\n", len(tokens), len(vocab))

	// 모델 생성
	fmt.Println("[2/5] Creating model...")
	model := NewSimpleModel(len(vocab), 64, 0.0)
	fmt.Printf("✅ Model created: vocab=%d, dModel=64\n\n", len(vocab))

	// Adam 옵티마이저 초기화
	fmt.Println("[3/5] Initializing Adam optimizer...")
	adam := NewAdamState(0.001, len(vocab)*64) // SGD와 동일한 LR로 비교
	fmt.Printf("✅ Adam: lr=0.001, beta1=0.9, beta2=0.999, eps=1e-8\n\n")

	// 학습 설정
	fmt.Println("[4/5] Training setup...")
	sequenceLen := 32
	batchSize := 64
	epochs := 10  // Priority 2와 동일하게 5 epochs (빠른 비교)
	numBatches := (len(tokens) - sequenceLen) / batchSize
	if numBatches > 500 {
		numBatches = 500 // CPU 친화적 배치 수
	}

	fmt.Printf("   Sequence length: %d\n", sequenceLen)
	fmt.Printf("   Batch size: %d\n", batchSize)
	fmt.Printf("   Batches per epoch: %d\n", numBatches)
	fmt.Printf("   Total epochs: %d\n", epochs)
	fmt.Printf("   Optimizer: Adam (lr=0.0001)\n\n")

	// 학습 루프
	fmt.Println("[5/5] Training...")
	fmt.Println("════════════════════════════════════════════════════════")

	losses := make([]float64, 0)
	gradNorms := make([]float64, 0)

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0
		epochGradNorm := 0.0
		batchCount := 0

		for batch := 0; batch < numBatches; batch++ {
			// 랜덤 위치에서 시퀀스 샘플
			startIdx := rand.Intn(len(tokens) - sequenceLen - 1)
			seq := tokens[startIdx : startIdx+sequenceLen]
			targetToken := tokens[startIdx+sequenceLen]

			// Forward pass
			logits := model.forward(seq)

			// Softmax
			probs := softmax(logits)

			// Loss
			loss := crossEntropyLoss(probs, targetToken)
			epochLoss += loss

			// Gradient 계산 (단순화: 정답 토큰 그래디언트만)
			grads := make([]float64, len(model.embedding)*len(model.embedding[0]))

			if targetToken < len(model.embedding) {
				grad := 1.0 - probs[targetToken]
				// 그래디언트를 배열에 패킹 (embedding과 동일 레이아웃)
				for j := 0; j < len(model.embedding[targetToken]); j++ {
					grads[targetToken*len(model.embedding[0])+j] = grad
				}
				epochGradNorm += grad * grad
			}

			// Gradient clipping
			clipped := ClipGradient(grads, 1.0)

			// Adam step
			flatParams := flattenEmbedding(model.embedding)
			updated := adam.Step(flatParams, clipped)
			model.embedding = unflattenEmbedding(updated, len(model.embedding), len(model.embedding[0]))

			batchCount++

			if batch%100 == 0 {
				avgLoss := epochLoss / float64(batchCount)
				ppl := math.Exp(avgLoss)
				fmt.Printf("Epoch %d, Batch %d/%d: Loss=%.4f, PPL=%.2f\r",
					epoch, batch+1, numBatches, avgLoss, ppl)
			}
		}

		if batchCount > 0 {
			avgEpochLoss := epochLoss / float64(batchCount)
			avgGradNorm := math.Sqrt(epochGradNorm / float64(batchCount))
			ppl := math.Exp(avgEpochLoss)
			losses = append(losses, avgEpochLoss)
			gradNorms = append(gradNorms, avgGradNorm)

			fmt.Printf("\n✅ Epoch %d: Loss=%.4f, PPL=%.2f, GradNorm=%.6f, AdamT=%d\n",
				epoch, avgEpochLoss, ppl, avgGradNorm, adam.T)
		}
	}

	// 결과 분석
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🎯 Training Complete!")
	fmt.Println("════════════════════════════════════════════════════════\n")

	fmt.Println("📊 Loss Trajectory:")
	for i, loss := range losses {
		ppl := math.Exp(loss)
		bar := ""
		if len(losses) > 1 && losses[0] > loss {
			barLen := int((losses[0] - loss) / losses[0] * 40)
			if barLen > 40 {
				barLen = 40
			}
			for j := 0; j < barLen; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %d: %s %.4f (PPL: %.2f)\n", i+1, bar, loss, ppl)
	}

	// 개선율
	if len(losses) > 1 {
		initialPPL := math.Exp(losses[0])
		finalPPL := math.Exp(losses[len(losses)-1])
		improvement := (initialPPL - finalPPL) / initialPPL * 100

		fmt.Printf("\n📈 Summary:\n")
		fmt.Printf("   Initial PPL: %.2f\n", initialPPL)
		fmt.Printf("   Final PPL:   %.2f\n", finalPPL)
		if improvement > 0 {
			fmt.Printf("   Improvement: %.1f%% ✅\n\n", improvement)
		} else {
			fmt.Printf("   Degradation: %.1f%% ⚠️\n\n", -improvement)
		}
	}

	// Adam 통계
	fmt.Println("📊 Adam Optimizer Statistics:")
	fmt.Printf("   Final T (timestep): %d\n", adam.T)
	fmt.Printf("   Final beta1^T: %.8f\n", math.Pow(adam.Beta1, float64(adam.T)))
	fmt.Printf("   Final beta2^T: %.8f\n", math.Pow(adam.Beta2, float64(adam.T)))
	fmt.Printf("   Bias correction 1: %.8f\n", 1.0-math.Pow(adam.Beta1, float64(adam.T)))
	fmt.Printf("   Bias correction 2: %.8f\n\n", 1.0-math.Pow(adam.Beta2, float64(adam.T)))

	fmt.Println("✅ Adam Training Complete!")
	fmt.Println("🔄 Comparison:")
	fmt.Println("   Priority 2 (SGD): 82%+ improvement, stable ✅")
	fmt.Println("   Priority 3 (Adam): See trajectory above")
	fmt.Println("   Reference: src/optimizer.fl (theoretical implementation)")
	fmt.Println("")
}

// ==================================================
// Helper Functions
// ==================================================

// flattenEmbedding embedding 테이블을 1D 배열로 변환
func flattenEmbedding(embedding [][]float64) []float64 {
	result := make([]float64, 0)
	for _, row := range embedding {
		result = append(result, row...)
	}
	return result
}

// unflattenEmbedding 1D 배열을 2D embedding으로 복원
func unflattenEmbedding(flat []float64, rows int, cols int) [][]float64 {
	result := make([][]float64, rows)
	for i := 0; i < rows; i++ {
		result[i] = make([]float64, cols)
		for j := 0; j < cols; j++ {
			if i*cols+j < len(flat) {
				result[i][j] = flat[i*cols+j]
			}
		}
	}
	return result
}

