	// 개선율
	if len(losses) > 1 {
		initialPPL := math.Exp(losses[0])
		finalPPL := math.Exp(losses[len(losses)-1])
		improvement := (initialPPL - finalPPL) / initialPPL * 100

		fmt.Printf("\n📈 Summary:\n")
		fmt.Printf("   Initial PPL: %.2f\n", initialPPL)
		fmt.Printf("   Final PPL:   %.2f\n", finalPPL)
		if improvement > 0 {
			fmt.Printf("   Improvement: %.1f%% ✅\n\n", improvement)
		} else {
			fmt.Printf("   Degradation: %.1f%% ⚠️\n\n", -improvement)
		}
	}

	// Adam 통계
	fmt.Println("📊 Adam Optimizer Statistics:")
	fmt.Printf("   Final T (timestep): %d\n", adam.T)
	fmt.Printf("   Final beta1^T: %.8f\n", math.Pow(adam.Beta1, float64(adam.T)))
	fmt.Printf("   Final beta2^T: %.8f\n", math.Pow(adam.Beta2, float64(adam.T)))
	fmt.Printf("   Bias correction 1: %.8f\n", 1.0-math.Pow(adam.Beta1, float64(adam.T)))
	fmt.Printf("   Bias correction 2: %.8f\n\n", 1.0-math.Pow(adam.Beta2, float64(adam.T)))

	fmt.Println("✅ Adam Training Complete!")
	fmt.Println("🔄 Comparison:")
	fmt.Println("   Priority 2 (SGD): 82%+ improvement, stable ✅")
	fmt.Println("   Priority 3 (Adam): See trajectory above")
	fmt.Println("   Reference: src/optimizer.fl (theoretical implementation)")
	fmt.Println("")
}

// ==================================================
// Helper Functions
// ==================================================

// flattenEmbedding embedding 테이블을 1D 배열로 변환
func flattenEmbedding(embedding [][]float64) []float64 {
	result := make([]float64, 0)
	for _, row := range embedding {
		result = append(result, row...)
	}
	return result
}

// unflattenEmbedding 1D 배열을 2D embedding으로 복원
func unflattenEmbedding(flat []float64, rows int, cols int) [][]float64 {
	result := make([][]float64, rows)
	for i := 0; i < rows; i++ {
		result[i] = make([]float64, cols)
		for j := 0; j < cols; j++ {
			if i*cols+j < len(flat) {
				result[i][j] = flat[i*cols+j]
			}
		}
	}
	return result
}

