package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// ==================================================
// MD 파일 수집 및 코퍼스 생성
// ==================================================

// collectMDFiles 서버 내 MD 파일들을 수집
func collectMDFiles() (string, int, error) {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  MD 파일 수집 - 서버 내 한글 마크다운 파일 통합        ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 수집 경로들
	searchPaths := []string{
		os.ExpandEnv("$HOME/projects"),
		os.ExpandEnv("$HOME/.projects"),
	}

	fmt.Println("[1/3] Scanning directories for .md files...")
	var allContent strings.Builder
	fileCount := 0
	totalSize := int64(0)

	for _, basePath := range searchPaths {
		fmt.Printf("  Scanning: %s\n", basePath)

		err := filepath.Walk(basePath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil // 접근 불가능한 파일 스킵
			}

			if !info.IsDir() && strings.HasSuffix(path, ".md") {
				// MD 파일 읽기
				content, err := ioutil.ReadFile(path)
				if err != nil {
					return nil
				}

				// 마크다운 태그 제거 (기본적인 정제)
				cleaned := cleanMarkdown(string(content))
				if len(cleaned) > 0 {
					allContent.WriteString(cleaned)
					allContent.WriteString("\n\n")
					fileCount++
					totalSize += info.Size()
				}
			}
			return nil
		})

		if err != nil {
			fmt.Printf("  ⚠️ Error scanning %s: %v\n", basePath, err)
		}
	}

	corpus := allContent.String()

	fmt.Printf("\n✅ Found %d MD files, Total size: %d bytes\n\n", fileCount, totalSize)

	// 통계
	fmt.Println("[2/3] Statistics:")
	lines := len(strings.Split(corpus, "\n"))
	chars := len(corpus)
	words := len(strings.Fields(corpus))

	fmt.Printf("  Lines: %d\n", lines)
	fmt.Printf("  Characters: %d\n", chars)
	fmt.Printf("  Words: %d\n", words)
	fmt.Printf("  Avg line length: %.1f chars\n\n", float64(chars)/float64(lines))

	// 파일로 저장
	fmt.Println("[3/3] Saving corpus...")
	corpusPath := "data/real_corpus_large.txt"
	err := ioutil.WriteFile(corpusPath, []byte(corpus), 0644)
	if err != nil {
		return "", 0, err
	}

	fmt.Printf("✅ Corpus saved: %s\n", corpusPath)
	fmt.Printf("✅ Corpus size: %d characters\n\n", len(corpus))

	return corpus, fileCount, nil
}

// cleanMarkdown 마크다운 태그 제거 및 기본 정제
func cleanMarkdown(content string) string {
	// 코드 블록 제거 (```...```)
	codeBlockRegex := regexp.MustCompile("(?s)```.*?```")
	content = codeBlockRegex.ReplaceAllString(content, "")

	// 인라인 코드 제거 (`)
	inlineCodeRegex := regexp.MustCompile("`[^`]+`")
	content = inlineCodeRegex.ReplaceAllString(content, "")

	// 마크다운 제목 기호 제거 (#)
	titleRegex := regexp.MustCompile("(?m)^#+\\s+")
	content = titleRegex.ReplaceAllString(content, "")

	// 굵은 글씨/이탤릭 제거 (**/__)
	content = strings.ReplaceAll(content, "**", "")
	content = strings.ReplaceAll(content, "__", "")
	content = strings.ReplaceAll(content, "*", "")
	content = strings.ReplaceAll(content, "_", "")

	// 링크 정제 ([text](url) -> text)
	linkRegex := regexp.MustCompile(`\[([^\]]+)\]\([^\)]+\)`)
	content = linkRegex.ReplaceAllString(content, "$1")

	// 리스트 기호 제거 (-, *, +, 번호)
	listRegex := regexp.MustCompile("(?m)^\\s*[-*+]\\s+|^\\s*\\d+\\.\\s+")
	content = listRegex.ReplaceAllString(content, "")

	// 테이블 구분선 제거 (|---|)
	tableRegex := regexp.MustCompile(`\|[-:| ]+\|`)
	content = tableRegex.ReplaceAllString(content, "")

	// 빈 줄 정리 (연속된 줄바꿈 -> 단일 줄바꿈)
	emptyLineRegex := regexp.MustCompile("\n\n\n+")
	content = emptyLineRegex.ReplaceAllString(content, "\n\n")

	// 앞뒤 공백 정리
	content = strings.TrimSpace(content)

	return content
}

// testMDCollection MD 수집 테스트
func testMDCollection() {
	corpus, fileCount, err := collectMDFiles()
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}

	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("📊 Corpus Sample (첫 500자):")
	fmt.Println("════════════════════════════════════════════════════════")
	if len(corpus) > 500 {
		fmt.Printf("%s...\n\n", corpus[:500])
	} else {
		fmt.Printf("%s\n\n", corpus)
	}

	fmt.Println("✅ MD 파일 수집 완료!")
	fmt.Printf("   Files collected: %d\n", fileCount)
	fmt.Printf("   Total characters: %d\n", len(corpus))
}

