	// 통계
	fmt.Println("[2/3] Statistics:")
	lines := len(strings.Split(corpus, "\n"))
	chars := len(corpus)
	words := len(strings.Fields(corpus))

	fmt.Printf("  Lines: %d\n", lines)
	fmt.Printf("  Characters: %d\n", chars)
	fmt.Printf("  Words: %d\n", words)
	fmt.Printf("  Avg line length: %.1f chars\n\n", float64(chars)/float64(lines))

	// 파일로 저장
	fmt.Println("[3/3] Saving corpus...")
	corpusPath := "data/real_corpus_large.txt"
	err := ioutil.WriteFile(corpusPath, []byte(corpus), 0644)
	if err != nil {
		return "", 0, err
	}

	fmt.Printf("✅ Corpus saved: %s\n", corpusPath)
	fmt.Printf("✅ Corpus size: %d characters\n\n", len(corpus))

	return corpus, fileCount, nil
}

