package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// ==================================================
// MD 파일 수집 및 코퍼스 생성
// ==================================================

// skipDirs 스킵할 디렉토리 이름들
var skipDirs = map[string]bool{
	"node_modules": true,
	".npm":         true,
	".git":         true,
	".cache":       true,
	"vendor":       true,
	"dist":         true,
	"build":        true,
	".gradle":      true,
	"__pycache__":  true,
	".venv":        true,
	"target":       true, // Rust/Maven build dir
}

// collectMDFiles 서버 내 MD + FL 파일들을 수집
func collectMDFiles() (string, int, error) {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  코드 코퍼스 수집 - MD + FL 파일 통합 (노이즈 제거)    ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 수집 경로들 (프로젝트 디렉토리만)
	searchPaths := []string{
		os.ExpandEnv("$HOME/projects"),
		os.ExpandEnv("$HOME/.projects"),
	}

	fmt.Println("[1/3] Scanning directories for .md and .fl files...")
	var allContent strings.Builder
	fileCount := 0
	totalSize := int64(0)
	mdCount := 0
	flCount := 0

	for _, basePath := range searchPaths {
		fmt.Printf("  Scanning: %s\n", basePath)

		err := filepath.Walk(basePath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return nil
			}

			// 스킵할 디렉토리 확인
			if info.IsDir() {
				if skipDirs[info.Name()] {
					return filepath.SkipDir
				}
				return nil
			}

			isMD := strings.HasSuffix(path, ".md")
			isFL := strings.HasSuffix(path, ".fl")

			if !isMD && !isFL {
				return nil
			}

			// 파일 크기 제한 (1MB 이상 스킵)
			if info.Size() > 1024*1024 {
				return nil
			}

			content, err := ioutil.ReadFile(path)
			if err != nil {
				return nil
			}

			var cleaned string
			if isMD {
				cleaned = cleanMarkdown(string(content))
				mdCount++
			} else {
				// FL 파일: 주석 제거 후 그대로 포함 (코드 학습)
				cleaned = cleanFLCode(string(content))
				flCount++
			}

			if len(strings.TrimSpace(cleaned)) > 50 {
				allContent.WriteString(cleaned)
				allContent.WriteString("\n\n")
				fileCount++
				totalSize += info.Size()
			}
			return nil
		})

		if err != nil {
			fmt.Printf("  ⚠️ Error scanning %s: %v\n", basePath, err)
		}
	}

	fmt.Printf("  MD files: %d, FL files: %d\n", mdCount, flCount)

	corpus := allContent.String()

	fmt.Printf("\n✅ Found %d MD files, Total size: %d bytes\n\n", fileCount, totalSize)

	// 통계
	fmt.Println("[2/3] Statistics:")
	lines := len(strings.Split(corpus, "\n"))
	chars := len(corpus)
	words := len(strings.Fields(corpus))

	fmt.Printf("  Lines: %d\n", lines)
	fmt.Printf("  Characters: %d\n", chars)
	fmt.Printf("  Words: %d\n", words)
	fmt.Printf("  Avg line length: %.1f chars\n\n", float64(chars)/float64(lines))

	// 파일로 저장
	fmt.Println("[3/3] Saving corpus...")
	corpusPath := "data/real_corpus_large.txt"
	err := ioutil.WriteFile(corpusPath, []byte(corpus), 0644)
	if err != nil {
		return "", 0, err
	}

	fmt.Printf("✅ Corpus saved: %s\n", corpusPath)
	fmt.Printf("✅ Corpus size: %d characters\n\n", len(corpus))

	return corpus, fileCount, nil
}

// cleanMarkdown 마크다운 태그 제거 및 기본 정제 (코드 블록은 보존)
func cleanMarkdown(content string) string {
	// 코드 블록 내용만 추출 (```lang\n코드\n``` → 코드만)
	codeBlockRegex := regexp.MustCompile("(?s)```[a-zA-Z]*\n(.*?)```")
	content = codeBlockRegex.ReplaceAllString(content, "$1")

	// 인라인 코드 보존 (백틱만 제거)
	inlineCodeRegex := regexp.MustCompile("`([^`]+)`")
	content = inlineCodeRegex.ReplaceAllString(content, "$1")

	// 마크다운 제목 기호 제거 (#)
	titleRegex := regexp.MustCompile("(?m)^#+\\s+")
	content = titleRegex.ReplaceAllString(content, "")

	// 굵은 글씨/이탤릭 제거
	content = strings.ReplaceAll(content, "**", "")
	content = strings.ReplaceAll(content, "__", "")

	// 링크 정제 ([text](url) -> text)
	linkRegex := regexp.MustCompile(`\[([^\]]+)\]\([^\)]+\)`)
	content = linkRegex.ReplaceAllString(content, "$1")

	// HTML 태그 제거
	htmlRegex := regexp.MustCompile("<[^>]+>")
	content = htmlRegex.ReplaceAllString(content, "")

	// 테이블 구분선 제거 (|---|)
	tableRegex := regexp.MustCompile(`\|[-:| ]+\|`)
	content = tableRegex.ReplaceAllString(content, "")

	// 빈 줄 정리
	emptyLineRegex := regexp.MustCompile("\n\n\n+")
	content = emptyLineRegex.ReplaceAllString(content, "\n\n")

	content = strings.TrimSpace(content)
	return content
}

// cleanFLCode FL 소스코드 정제 (주석 제거, 공백 정리)
func cleanFLCode(content string) string {
	// 한 줄 주석 제거 (//)
	lineCommentRegex := regexp.MustCompile(`(?m)//.*$`)
	content = lineCommentRegex.ReplaceAllString(content, "")

	// 블록 주석 제거 (/* ... */)
	blockCommentRegex := regexp.MustCompile(`(?s)/\*.*?\*/`)
	content = blockCommentRegex.ReplaceAllString(content, "")

	// 빈 줄 정리
	emptyLineRegex := regexp.MustCompile("\n\n\n+")
	content = emptyLineRegex.ReplaceAllString(content, "\n\n")

	content = strings.TrimSpace(content)
	return content
}

// testMDCollection MD 수집 테스트
func testMDCollection() {
	corpus, fileCount, err := collectMDFiles()
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}

	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("📊 Corpus Sample (첫 500자):")
	fmt.Println("════════════════════════════════════════════════════════")
	if len(corpus) > 500 {
		fmt.Printf("%s...\n\n", corpus[:500])
	} else {
		fmt.Printf("%s\n\n", corpus)
	}

	fmt.Println("✅ MD 파일 수집 완료!")
	fmt.Printf("   Files collected: %d\n", fileCount)
	fmt.Printf("   Total characters: %d\n", len(corpus))
}

