package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 4: d_model=128 + Single-Head Self-Attention
// 자기-참조 AI: FreeLang이 FreeLang을 학습
// ==================================================

// AttentionModel 임베딩 + 단일 헤드 어텐션 + 프로젝션
type AttentionModel struct {
	vocabSize int
	dModel    int

	// Embedding [vocab, dModel]
	embedding [][]float64

	// Self-Attention Q, K, V, O 가중치 [dModel, dModel]
	Wq [][]float64
	Wk [][]float64
	Wv [][]float64
	Wo [][]float64

	// Output projection [dModel, vocab]
	proj [][]float64
}

// newAttentionModel AttentionModel 생성 (d_model=128)
func newAttentionModel(vocabSize, dModel int) *AttentionModel {
	m := &AttentionModel{
		vocabSize: vocabSize,
		dModel:    dModel,
	}

	scale := math.Sqrt(2.0 / float64(dModel+dModel))
	vocabScale := math.Sqrt(2.0 / float64(vocabSize+dModel))

	// Embedding 초기화
	m.embedding = make2D(vocabSize, dModel, vocabScale)

	// Attention 가중치 초기화
	m.Wq = make2D(dModel, dModel, scale)
	m.Wk = make2D(dModel, dModel, scale)
	m.Wv = make2D(dModel, dModel, scale)
	m.Wo = make2D(dModel, dModel, scale)

	// Output projection 초기화
	m.proj = make2D(dModel, vocabSize, vocabScale)

	return m
}

// make2D Xavier 초기화된 2D 행렬 생성
func make2D(rows, cols int, scale float64) [][]float64 {
	mat := make([][]float64, rows)
	for i := range mat {
		mat[i] = make([]float64, cols)
		for j := range mat[i] {
			// 결정적 초기화 (sin 기반 pseudo-random)
			mat[i][j] = math.Sin(float64(i*cols+j)*0.1) * scale
		}
	}
	return mat
}

// forwardAttention 시퀀스 forward pass (단일 헤드 어텐션)
// seq: []int 토큰 ID 배열
// return: []float64 logits (vocab 크기)
func (m *AttentionModel) forwardAttention(seq []int) []float64 {
	seqLen := len(seq)
	d := m.dModel

	// 1. Embedding lookup → [seqLen, dModel]
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}

	// 2. Q, K, V 계산
	Q := matmul2D(X, m.Wq) // [seqLen, dModel]
	K := matmul2D(X, m.Wk)
	V := matmul2D(X, m.Wv)

	// 3. Scaled dot-product attention (causal)
	scale := 1.0 / math.Sqrt(float64(d))
	attnOut := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		// scores[j] = Q[i] · K[j] / sqrt(d)  (j <= i만 허용, causal mask)
		scores := make([]float64, seqLen)
		for j := 0; j <= i; j++ {
			dot := 0.0
			for k := 0; k < d; k++ {
				dot += Q[i][k] * K[j][k]
			}
			scores[j] = dot * scale
		}
		// causal mask: j > i → -inf
		for j := i + 1; j < seqLen; j++ {
			scores[j] = -1e9
		}

		// Softmax
		probs := softmax1D(scores)

		// Attention output = probs · V
		attnOut[i] = make([]float64, d)
		for j := 0; j < seqLen; j++ {
			for k := 0; k < d; k++ {
				attnOut[i][k] += probs[j] * V[j][k]
			}
		}
	}

	// 4. Output projection Wo
	attnProj := matmul2D(attnOut, m.Wo) // [seqLen, dModel]

	// 5. Residual connection
	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			attnProj[i][j] += X[i][j]
		}
	}

	// 6. 마지막 토큰 위치 → logits
	last := attnProj[seqLen-1] // [dModel]
	logits := make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		sum := 0.0
		for k := 0; k < d; k++ {
			sum += last[k] * m.proj[k][v]
		}
		logits[v] = sum
	}

	return logits
}

// matmul2D [A, K] @ [K, B] → [A, B]
func matmul2D(a [][]float64, b [][]float64) [][]float64 {
	A := len(a)
	K := len(a[0])
	B := len(b[0])
	out := make([][]float64, A)
	for i := range out {
		out[i] = make([]float64, B)
		for j := 0; j < B; j++ {
			sum := 0.0
			for k := 0; k < K; k++ {
				sum += a[i][k] * b[k][j]
			}
			out[i][j] = sum
		}
	}
	return out
}

// softmax1D 1D 배열 softmax (수치 안정)
func softmax1D(x []float64) []float64 {
	max := x[0]
	for _, v := range x {
		if v > max {
			max = v
		}
	}
	sum := 0.0
	out := make([]float64, len(x))
	for i, v := range x {
		out[i] = math.Exp(v - max)
		sum += out[i]
	}
	for i := range out {
		out[i] /= sum
	}
	return out
}

