	return logits
}

// matmul2D [A, K] @ [K, B] → [A, B]
func matmul2D(a [][]float64, b [][]float64) [][]float64 {
	A := len(a)
	K := len(a[0])
	B := len(b[0])
	out := make([][]float64, A)
	for i := range out {
		out[i] = make([]float64, B)
		for j := 0; j < B; j++ {
			sum := 0.0
			for k := 0; k < K; k++ {
				sum += a[i][k] * b[k][j]
			}
			out[i][j] = sum
		}
	}
	return out
}

// softmax1D 1D 배열 softmax (수치 안정)
func softmax1D(x []float64) []float64 {
	max := x[0]
	for _, v := range x {
		if v > max {
			max = v
		}
	}
	sum := 0.0
	out := make([]float64, len(x))
	for i, v := range x {
		out[i] = math.Exp(v - max)
		sum += out[i]
	}
	for i := range out {
		out[i] /= sum
	}
	return out
}

