func trainWithAttention() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 4: d_model=128 + Single-Head Self-Attention    ║")
	fmt.Println("║  자기-참조 AI: FreeLang이 FreeLang 문법을 학습         ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 데이터 로드
	fmt.Println("[1/5] Loading tokenized data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	// 모델 생성 (d_model=128)
	fmt.Println("[2/5] Creating model (d_model=128)...")
	model := newAttentionModel(len(vocab), 128)
	paramCount := len(vocab)*128*2 + 128*128*4 + 128*len(vocab)
	fmt.Printf("✅ Model: vocab=%d, d_model=128\n", len(vocab))
	fmt.Printf("   Parameters: ~%dk\n\n", paramCount/1000)

	// Adam 인스턴스 분리 (embedding, proj 각각)
	fmt.Println("[3/5] Initializing Adam (lr=0.0003, cosine decay)...")
	adamEmb  := NewAdamState(0.0003, len(vocab)*128)
	adamProj := NewAdamState(0.0003, 128*len(vocab))
	_ = paramCount
	fmt.Printf("✅ Adam x2 (embedding + proj) ready\n\n")

	// 학습 설정
	seqLen := 32
	epochs := 10
	numBatches := 500
	warmupSteps := 500
	totalSteps := epochs * numBatches

	fmt.Println("[4/5] Training setup...")
	fmt.Printf("   d_model: 128 (이전: 64)\n")
	fmt.Printf("   Attention: Single-head, causal mask\n")
	fmt.Printf("   Sequence: %d tokens\n", seqLen)
	fmt.Printf("   Batches/epoch: %d\n", numBatches)
	fmt.Printf("   Epochs: %d\n\n", epochs)

	// 학습
	fmt.Println("[5/5] Training...")
	fmt.Println("════════════════════════════════════════════════════════")

	losses := make([]float64, 0)

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			// 랜덤 시퀀스 샘플
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			// Forward
			logits := model.forwardAttention(seq)
			probs := softmax1D(logits)

			// Loss
			loss := 0.0
			if targetTok < len(probs) && probs[targetTok] > 0 {
				loss = -math.Log(probs[targetTok])
			} else {
				loss = math.Log(float64(len(vocab)))
			}
			epochLoss += loss

			// Gradient (softmax cross-entropy: dL/dlogit = probs - one_hot)
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) {
				dLogits[targetTok] -= 1.0
			}

			// Cosine LR decay
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.LearningRate = lr

			// 1) proj 가중치 업데이트: dL/dproj[k,v] = last[k] * dLogits[v]
			// last 벡터를 forward에서 재계산 (근사: embedding의 마지막 토큰 사용)
			lastTok := seq[seqLen-1]
			flatProj := flattenEmbedding(model.proj) // [dModel, vocab]
			gradsProj := make([]float64, len(flatProj))
			if lastTok < model.vocabSize {
				for k := 0; k < model.dModel; k++ {
					for v := 0; v < model.vocabSize; v++ {
						gradsProj[k*model.vocabSize+v] = model.embedding[lastTok][k] * dLogits[v]
					}
				}
			}
			clippedProj := ClipGradient(gradsProj, 0.1)
			updatedProj := adam.Step(flatProj, clippedProj)
			model.proj = unflattenEmbedding(updatedProj, model.dModel, model.vocabSize)

			// 2) Embedding 업데이트: dL/demb[tok, k] = sum_v(proj[k,v] * dLogits[v])
			flatEmb := flattenEmbedding(model.embedding)
			gradsEmb := make([]float64, len(flatEmb))
			if targetTok < model.vocabSize {
				for k := 0; k < model.dModel; k++ {
					dEmb := 0.0
					for v := 0; v < model.vocabSize; v++ {
						dEmb += model.proj[k][v] * dLogits[v]
					}
					gradsEmb[targetTok*model.dModel+k] = dEmb
				}
			}
			clipped := ClipGradient(gradsEmb, 0.1)
			updated := adam.Step(flatEmb, clipped)
			model.embedding = unflattenEmbedding(updated, model.vocabSize, model.dModel)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %d, Batch %d/%d: Loss=%.4f, PPL=%.2f, LR=%.6f\r",
					epoch, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		fmt.Printf("\n✅ Epoch %d: Loss=%.4f, PPL=%.2f\n", epoch, avgLoss, math.Exp(avgLoss))
	}

	// 결과
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("📊 Loss Trajectory:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Summary:\n")
		fmt.Printf("   d_model:     128 (이전: 64)\n")
		fmt.Printf("   Attention:   Single-head causal ✅\n")
		fmt.Printf("   Initial PPL: %.2f\n", iPPL)
		fmt.Printf("   Final PPL:   %.2f\n", fPPL)
		if imp > 0 {
			fmt.Printf("   Improvement: %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   Degradation: %.1f%% ⚠️\n\n", -imp)
		}
	}
}

package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 4: d_model=128 + Single-Head Self-Attention
// 자기-참조 AI: FreeLang이 FreeLang을 학습
// ==================================================

// AttentionModel 임베딩 + 단일 헤드 어텐션 + 프로젝션
type AttentionModel struct {
	vocabSize int
	dModel    int

	// Embedding [vocab, dModel]
	embedding [][]float64

	// Self-Attention Q, K, V, O 가중치 [dModel, dModel]
	Wq [][]float64
	Wk [][]float64
	Wv [][]float64
	Wo [][]float64

	// Output projection [dModel, vocab]
	proj [][]float64
}

// newAttentionModel AttentionModel 생성 (d_model=128)
func newAttentionModel(vocabSize, dModel int) *AttentionModel {
	m := &AttentionModel{
		vocabSize: vocabSize,
		dModel:    dModel,
	}

	scale := math.Sqrt(2.0 / float64(dModel+dModel))
	vocabScale := math.Sqrt(2.0 / float64(vocabSize+dModel))

	// Embedding 초기화
	m.embedding = make2D(vocabSize, dModel, vocabScale)

	// Attention 가중치 초기화
	m.Wq = make2D(dModel, dModel, scale)
	m.Wk = make2D(dModel, dModel, scale)
	m.Wv = make2D(dModel, dModel, scale)
	m.Wo = make2D(dModel, dModel, scale)

	// Output projection 초기화
	m.proj = make2D(dModel, vocabSize, vocabScale)

	return m
}

// make2D Xavier 초기화된 2D 행렬 생성
func make2D(rows, cols int, scale float64) [][]float64 {
	mat := make([][]float64, rows)
	for i := range mat {
		mat[i] = make([]float64, cols)
		for j := range mat[i] {
			// 결정적 초기화 (sin 기반 pseudo-random)
			mat[i][j] = math.Sin(float64(i*cols+j)*0.1) * scale
		}
	}
	return mat
}

// forwardAttention 시퀀스 forward pass (단일 헤드 어텐션)
// seq: []int 토큰 ID 배열
// return: []float64 logits (vocab 크기)
func (m *AttentionModel) forwardAttention(seq []int) []float64 {
	seqLen := len(seq)
	d := m.dModel

	// 1. Embedding lookup → [seqLen, dModel]
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}

	// 2. Q, K, V 계산
	Q := matmul2D(X, m.Wq) // [seqLen, dModel]
	K := matmul2D(X, m.Wk)
	V := matmul2D(X, m.Wv)

	// 3. Scaled dot-product attention (causal)
	scale := 1.0 / math.Sqrt(float64(d))
	attnOut := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		// scores[j] = Q[i] · K[j] / sqrt(d)  (j <= i만 허용, causal mask)
		scores := make([]float64, seqLen)
		for j := 0; j <= i; j++ {
			dot := 0.0
			for k := 0; k < d; k++ {
				dot += Q[i][k] * K[j][k]
			}
			scores[j] = dot * scale
		}
		// causal mask: j > i → -inf
		for j := i + 1; j < seqLen; j++ {
			scores[j] = -1e9
		}

		// Softmax
		probs := softmax1D(scores)

		// Attention output = probs · V
		attnOut[i] = make([]float64, d)
		for j := 0; j < seqLen; j++ {
			for k := 0; k < d; k++ {
				attnOut[i][k] += probs[j] * V[j][k]
			}
		}
	}

	// 4. Output projection Wo
	attnProj := matmul2D(attnOut, m.Wo) // [seqLen, dModel]

	// 5. Residual connection
	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			attnProj[i][j] += X[i][j]
		}
	}

	// 6. 마지막 토큰 위치 → logits
	last := attnProj[seqLen-1] // [dModel]
	logits := make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		sum := 0.0
		for k := 0; k < d; k++ {
			sum += last[k] * m.proj[k][v]
		}
		logits[v] = sum
	}

	return logits
}

// matmul2D [A, K] @ [K, B] → [A, B]
func matmul2D(a [][]float64, b [][]float64) [][]float64 {
	A := len(a)
	K := len(a[0])
	B := len(b[0])
	out := make([][]float64, A)
	for i := range out {
		out[i] = make([]float64, B)
		for j := 0; j < B; j++ {
			sum := 0.0
			for k := 0; k < K; k++ {
				sum += a[i][k] * b[k][j]
			}
			out[i][j] = sum
		}
	}
	return out
}

// softmax1D 1D 배열 softmax (수치 안정)
func softmax1D(x []float64) []float64 {
	max := x[0]
	for _, v := range x {
		if v > max {
			max = v
		}
	}
	sum := 0.0
	out := make([]float64, len(x))
	for i, v := range x {
		out[i] = math.Exp(v - max)
		sum += out[i]
	}
	for i := range out {
		out[i] /= sum
	}
	return out
}

